				slog.String("marker_sha", m.StartingSHA),
				slog.String("head_sha", headSHA))
			if clearErr := ClearPendingReviewMarker(ctx); clearErr != nil {
				logging.Debug(ctx, "failed to clear stale marker", slog.String("error", clearErr.Error()))
